package main

import "fmt"

func main() {
	capitals := map[string]string{
		"USA":    "Washington DC",
		"India":  "New Delhi",
		"France": "Paris",
		"Japan":  "Tokyo",
	}

	fmt.Println("All capitals:")
	for country, capital := range capitals {
		fmt.Printf("%s -> %s\n", country, capital)
	}

	if cap, ok := capitals["India"]; ok {
		fmt.Println("Found India:", cap)
	}

	fmt.Println("Number of entries:", len(capitals))
}
